const C=window.SITE_CONFIG;
const page=document.body.dataset.page||'home';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name='shield')=>{const paths={pause:'M9 5v14M15 5v14',play:'m8 4 11 8-11 8V4Z',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z M8 12l3 3 5-6',arrow:'M5 12h14m-6-6 6 6-6 6',left:'M19 12H5m6-6-6 6 6 6',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Zm5-2 6 6',mail:'M3 5h18v14H3V5Zm0 0 9 8 9-8',home:'m3 10 9-7 9 7v11H3V10Zm6 11v-8h6v8',leaf:'M20 3C7 2 2 8 5 15s15 5 15-12ZM5 20 16 8',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v6l4 2',layers:'m3 8 9-5 9 5-9 5-9-5Zm0 5 9 5 9-5M3 18l9 5 9-5'};return `<svg class="ui" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.shield}"/></svg>`};
const pest=(name='roach',cls='icon')=>`<img class="${cls}" src="assets/${name}.avif" alt="" width="80" height="80">`;
const img=(name,alt,cls='photo')=>`<img class="${cls}" src="assets/${name}.avif" alt="${alt}" width="1200" height="800" decoding="async">`;
const btn=(text,href='contact.html',cls='')=>`<a class="button ${cls}" href="${href}"><span>${text}</span>${/banner-button|dark-button/.test(cls)?`<span class="button-mark" aria-hidden="true">${icon('arrow')}</span>`:''}</a>`;
const brand=()=>`<a class="brand" href="index.html"><img src="${esc(C.logo)}" alt="" width="48" height="48"><span>${esc(C.companyName)}</span></a>`;
const cloud=()=>``;
const section=(id,content,cls='')=>`<section id="${id}" class="section ${cls}"><div class="container">${content}</div></section>`;
const head=(title,desc='',center=false)=>`<div class="section-head ${center?'center':''}" data-aos="fade-up"><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>`;
const feature=(title,text,n='check')=>`<div class="feature"><span class="check">${icon(n)}</span><div><h3>${title}</h3><p>${text}</p></div></div>`;
const frame=(n,alt)=>`<div class="photo-frame" data-aos="fade-up">${img(n,alt)}</div>`;
const services=[{id:'household',title:'Household pests',pest:'roach',photo:'cockroach',desc:'From kitchen corners to hidden cracks. Explore options for cockroaches, ants and other unwelcome guests.'},{id:'termites',title:'Termite control',pest:'termite',photo:'timber',desc:'Understand the signs in timber, what an inspection covers and which questions to ask a specialist.'},{id:'rodents',title:'Rodent control',pest:'mouse',photo:'exterior',desc:'Look beyond the sighting. Compare inspection, entry-point sealing and monitoring approaches.'}];
const marquee=()=>`<div class="marquee"><div class="container"><div class="marquee-track">${Array.from({length:2},()=>['A calmer home','Know your pest','Explore your options','Find your next step'].map((s,i)=>`<span>${pest(['roach','ant','termite','mouse'][i])}${s}</span>`).join('')).join('')}</div></div></div>`;
const compare=(id,photo,type='roach',label='A clearer space')=>`<section class="compare-section" id="${id}" aria-label="Illustrated before and after"><div class="${page==='home'?'container':''}"><div class="compare">${img(photo,'Illustrative room scene','scene')}<div class="compare-before">${Array.from({length:7},(_,i)=>`<img class="pest-cut" src="assets/real-${type}.avif" alt="" style="left:${8+i*13}%;top:${30+(i%3)*18}%;rotate:${[12,-18,28,-9,17,-25,8][i]}deg">`).join('')}</div><span class="compare-label">Before · signs of activity</span><span class="compare-label after">After · ${label}</span><div class="compare-line"><span>${icon('left')}${icon('arrow')}</span></div><span class="compare-caption">Interactive illustration · drag to explore, not a treatment result</span><input type="range" min="0" max="100" value="50" aria-label="Reveal before and after"></div></div></section>`;
const questions=[['How does this platform work?','Explore the guides, choose the service that fits your concern and send an enquiry. We can help you discuss your needs with an independent provider. Availability varies by location.'],['Do you carry out pest treatments?','No. We are an independent discovery platform. Any inspection, quotation or treatment is agreed directly with the provider you choose.'],['What should I include in my enquiry?','Tell us what you have noticed, where it is happening, how long it has been present and whether children or pets use the space. Avoid including sensitive personal information.'],['Can I compare different approaches?','Yes. Ask providers about inspection findings, the proposed method, preparation, follow-up and the full written quotation. The right approach depends on the property and the identified pest.']];
const faq=qs=>`<div class="accordion">${qs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
const banner=(id,title)=>`<div class="service-banner"><div class="banner-light"></div><img class="banner-person" src="assets/person-${id}.avif" alt="Pest control professional"><div class="banner-content"><h2>${title}</h2><p>A clearer conversation. A more confident next step.</p>${btn('Explore your options','contact.html','banner-button')}</div></div>`;
function home(){return `<section class="hero"><div class="hero-shell">${['hero','hero-2','hero-3'].map((n,i)=>`<img class="hero-bg hero-frame ${i===0?'is-active':''}" src="assets/${n}.avif" alt="Pest control inspection at a home" ${i===0?'fetchpriority="high"':'decoding="async"'}>`).join('')}<div class="hero-shape"></div><div class="container"><div class="hero-copy"><h1>A calmer home.<br>Without the pests.</h1><p>Understand the signs. Explore your options. Find the right pest control support for the place you call home.</p><div class="buttons">${btn('Explore pest control','household.html')}${btn('Get to know us','about.html','outline')}</div><div class="hero-note"><span class="hero-stamp">${icon('shield')}</span><span>Independent guidance.<br>Your home. Your next step.</span></div></div></div><div class="hero-slide-controls" aria-label="Hero photographs">${[0,1,2].map(i=>`<button data-hero-slide="${i}" aria-label="Show photograph ${i+1}" aria-pressed="${i===0}"><span></span></button>`).join('')}<button class="hero-pause" aria-label="Pause slideshow" aria-pressed="false">${icon('pause')}</button></div></div></section>${marquee()}
${section('about-preview',`<div class="split"><div class="collage" data-aos="fade-up">${img('inspection-kitchen','Professional inspecting a kitchen cabinet','main-photo')}${img('pantry','A clean pantry with well sealed food containers','small-photo')}<div class="photo-label"><b>Home first.</b>Every detail matters.</div></div><div data-aos="fade-up"><h2>A little knowledge.<br>A better next step.</h2><p style="margin-top:22px">Unwelcome visitors can make a familiar place feel different. We bring pest control options into focus, so you can start a useful conversation with an independent specialist.</p><div class="features">${feature('Understand the signs','Know what to notice before you enquire.','search')}${feature('Explore the approach','Compare the questions that really matter.','shield')}</div><p class="mini">Your home, your priorities. Clear information without the pressure.</p><div class="buttons">${btn('More about us','about.html')}</div></div></div>`)}
${section('services',`${head('Find the right support.','Explore three focused guides to common pest concerns, inspection and prevention.')}<div class="swiper service-swiper"><div class="swiper-wrapper">${[...services,...services].map(s=>`<article class="swiper-slide service-card"><div class="photo-frame">${img(s.photo,s.title+' inspection')}</div><div class="card-body">${pest(s.pest)}<h3>${s.title}</h3><p>${s.desc}</p><a class="text-link" href="${s.id}.html">Explore this service</a></div></article>`).join('')}</div></div><div class="slider-controls"><div class="swiper-pagination"></div><div class="slider-buttons"><button class="circle-btn swiper-prev" aria-label="Previous services">${icon('left')}</button><button class="circle-btn swiper-next" aria-label="Next services">${icon('arrow')}</button></div></div>`,'pale')}
${section('treatment-guide',`${head('Different pests.<br>Different approaches.','Hover or tap a card to meet the pests each approach may be used to address.')}<div class="split"><div class="photo-frame">${img('flashlight','Specialist examining a space with an inspection flashlight')}<div class="photo-overlay"><b>Start with identification.</b><p>A provider should identify the pest before suggesting a treatment.</p></div></div><div class="tool-list">${[['Inspection & monitoring','Locate activity and understand its pattern.','roach','search'],['Targeted bait systems','Discuss contained options for ants or cockroaches.','ant','target'],['Timber protection','Ask about termite-specific inspection and protection.','termite','shield'],['Entry-point exclusion','Explore sealing and monitoring for rodents.','mouse','home']].map(([t,d,p,i])=>`<button class="tool-card">${icon(i)}<span><h3>${t}</h3><p>${d}</p></span>${pest(p,'hover-pest')}</button>`).join('')}</div></div>`)}
${compare('before-after','living-room','roach','a calmer room')}
${section('pest-library',`${head('Meet the uninvited.','A closer look at familiar pests. Identification should be confirmed by a qualified provider.',true)}<div class="pest-grid">${[['Cockroaches','Warm, sheltered kitchen spaces.','roach'],['Ants','Small trails near food or moisture.','ant'],['Termites','Activity around timber and soil.','termite'],['Rodents','Shelter, gaps and accessible food.','mouse']].map(([t,d,p])=>`<a href="${p==='termite'?'termites':p==='mouse'?'rodents':'household'}.html" class="pest-card" data-aos="fade-up">${pest(p,'pest-art')}<h3>${t}</h3><p>${d}</p></a>`).join('')}</div>`,'pale')}
${section('room-explorer',`<div class="split"><div><h2>Look a little closer.</h2><p style="margin-top:22px">Hidden guests love quiet corners. Explore this room, reveal the visitors and try the interactive tools.</p><div class="game-tools"><button class="active" data-mode="tap" aria-pressed="true">Tap to clear</button><button data-mode="spray" aria-pressed="false">Try the spray</button><button data-reveal aria-pressed="false">Reveal pests</button><button data-reset>Reset</button></div><p class="game-status" aria-live="polite">Find all 6 visitors.</p><p class="mini">A playful illustration, not pesticide application advice.</p></div><div class="room-game" tabindex="0" aria-label="Interactive kitchen pest search">${img('kitchen','Sunlit kitchen with hidden interactive pests')}${Array.from({length:6},(_,i)=>`<button class="game-pest" style="left:${10+i*14}%;top:${42+(i%3)*17}%" aria-label="Clear hidden pest ${i+1}">${pest(i%2?'ant':'roach')}</button>`).join('')}</div></div>`)}
${section('methods',`${head('What’s in the toolkit?','Learn the purpose of common approaches before asking a provider for a property-specific plan.')}<div class="tabs" role="tablist" aria-label="Pest control approaches">${['Bait stations','Monitoring','Exclusion'].map((t,i)=>`<button role="tab" id="tab-${i}" aria-controls="panel-${i}" aria-selected="${i===0}" data-tab="${i}">${t}</button>`).join('')}</div><div class="split"><div class="tab-visual">${img('fence','Pest control professional inspecting a garden boundary')}<div class="photo-overlay"><b>Ask. Compare. Understand.</b><p>Methods depend on the pest, site and provider assessment.</p></div></div><div>${[['Target the activity.','Bait systems are designed around the identified pest and its behaviour. Ask a provider about placement, access restrictions and follow-up.',['Which pest has been identified?','How will the system be checked?','What access precautions apply?']],['Understand the pattern.','Monitoring helps a provider understand where and when activity occurs, and whether the agreed plan needs to change.',['Where are the activity points?','When should monitoring be reviewed?','How will findings be recorded?']],['Close the openings.','Exclusion focuses on the gaps that allow pests to enter. Ask what can be sealed, what needs ventilation and how it will be checked.',['Which entry points were found?','What materials suit the opening?','How can new gaps be prevented?']]].map(([t,d,items],i)=>`<div class="tab-content" id="panel-${i}" role="tabpanel" aria-labelledby="tab-${i}" ${i?'hidden':''}><h3>${t}</h3><p style="margin-top:18px">${d}</p><ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul>${btn('Discuss your concern')}</div>`).join('')}</div></div>`,'pale')}
${section('hidden-places',`${head('The places we overlook.','Select a point to explore the small details that deserve a closer look.')}<div class="split"><div class="hotspots">${img('threshold','Close view of an exterior threshold and small gaps')}${[[24,68],[65,40],[85,77]].map(([x,y],i)=>`<button class="hotspot ${i===0?'active':''}" style="left:${x}%;top:${y}%" data-spot="${i}" aria-label="Inspect ${['threshold gap','frame joint','sheltered corner'][i]}">${icon('plus')}</button>`).join('')}</div><div class="spot-card"><span class="tag">Closer inspection</span><h3 id="spot-title">Under the threshold</h3><p id="spot-description">A small gap can be easy to miss. Ask a provider to assess whether the threshold, door sweep or surrounding joint needs attention.</p><div class="features">${feature('Look for changes','Note gaps, wear and repeated activity.','search')}${feature('Keep a record','A clear photo can help explain the concern.','layers')}</div><div class="spot-record"><b>Your observation checklist</b><span>Exact location · Time noticed · Visible changes</span><p>Photograph accessible details from a safe position. Keep your observations together for the provider; a photograph supports the conversation but does not confirm identification.</p></div><div class="spot-nav"><button class="circle-btn" data-spot-prev aria-label="Previous location">${icon('left')}</button><button class="circle-btn" data-spot-next aria-label="Next location">${icon('arrow')}</button></div></div></div>`)}
${section('questions',`${head('Good questions.<br>Clearer choices.','Start here before you choose an independent pest control provider.')}<div class="faq-grid"><div class="faq-art">${img('pipe','Professional sealing a utility entry point')}<div class="photo-overlay"><b>Your next step starts here.</b><p>Describe what you have noticed. We will help you explore the options.</p>${btn('Make an enquiry')}</div></div>${faq(questions)}</div>`,'pale')}`}
const serviceData={household:{headline:'Small pests.<br>A fresh start.',lead:'From pantry trails to quiet kitchen corners, understand household pest activity before choosing your next step.',intro:'Make sense of the signs.',body:'A sighting is a starting point. The room, the pattern and the conditions around it all help an independent specialist understand the concern.',photo:'sink',side:'bed',compare:'house-clean',pest:'roach',signs:[['Kitchen activity','Note repeated sightings near cabinets, warmth or food.','roach'],['Visible trails','Record where a trail starts and the rooms it reaches.','ant'],['Hidden shelter','Check accessible corners without disturbing suspected nesting.','roach']],process:['Describe the activity','Discuss identification','Review the proposed plan'],choices:['Kitchen','Living spaces','Several rooms'],answers:['Describe activity near cupboards, plumbing and food storage. Ask how preparation and follow-up are handled.','Tell the provider which rooms are affected and where people or pets spend time. Ask about access restrictions.','List the rooms and whether sightings occur at similar times. A whole-property assessment may clarify the pattern.'],cta:'Bring comfort home.',qs:[['Is one sighting enough to enquire?','Yes. Describe what you saw and where. A provider can explain whether an inspection is appropriate.'],['Should I move furniture or empty cupboards?','Wait for the provider’s preparation instructions. Requirements vary by method and the affected space.'],['How is follow-up decided?','Ask the provider what signs they will review and when. There is no single schedule for every pest or property.']]},termites:{headline:'Protect your home.<br>Down to the timber.',lead:'Explore termite inspection, timber concerns and the questions that make a specialist conversation more useful.',intro:'Look beyond the surface.',body:'Timber changes deserve context. A specialist can assess the structure, accessible areas and signs of activity before recommending a property-specific approach.',photo:'damage',side:'attic',compare:'timber-clean',pest:'termite',signs:[['Timber changes','Record damaged or altered accessible wood.','termite'],['Soil connections','Mention timber close to soil or damp areas.','ant'],['Concealed spaces','Ask which areas are accessible during an inspection.','termite']],process:['Map the concern','Understand the inspection','Compare protection options'],choices:['Timber concern','Preventive inspection','Previous treatment'],answers:['Share clear photos and the exact location. Avoid breaking open the area before the provider has advised you.','Ask what is inspected, which areas are inaccessible and how the findings are documented.','Share any records of previous work. Ask how those records affect the proposed inspection and next steps.'],cta:'Give your home<br>a closer look.',qs:[['Can a photo confirm termites?','A photo can help explain your concern but may not be enough to identify the pest or the extent of activity.'],['Will every space be inspected?','Access depends on the building. Ask the provider to record any areas that cannot be inspected.'],['What should a quotation explain?','Ask for the proposed scope, method, limitations, preparation, follow-up and full cost in writing.']]},rodents:{headline:'Close the gaps.<br>Restore the calm.',lead:'Explore rodent inspection, entry-point exclusion and monitoring with a clearer idea of what to ask.',intro:'Follow the entry points.',body:'A useful assessment looks at more than the visitor. Shelter, access routes and food sources all help inform an independent provider’s plan.',photo:'mouse-garage',side:'garage-seal',compare:'rodent-clean',pest:'mouse',signs:[['Repeated sounds','Record the room and time you notice activity.','mouse'],['Access gaps','Mention accessible gaps near pipes or thresholds.','ant'],['Food access','Describe storage areas and visible damage to packaging.','mouse']],process:['Record the pattern','Assess entry routes','Plan exclusion & monitoring'],choices:['Inside the home','Garage or outbuilding','Recurring activity'],answers:['Tell the provider which rooms are affected and whether activity is visible or only heard. Ask about the inspection scope.','Describe doors, stored items and accessible gaps. Ask how the proposed plan preserves ventilation and utility access.','Share previous actions and when signs returned. Ask how entry points and follow-up will be reassessed.'],cta:'A home with<br>fewer openings.',qs:[['Is sealing a gap always the first step?','A provider should assess the activity and access routes before deciding the sequence of work.'],['What information helps a provider?','The location, frequency and timing of signs, accessible gaps and any previous actions are useful starting points.'],['How can I compare plans?','Compare the inspection scope, exclusion work, monitoring, access precautions and follow-up terms.']]}};
function service(){const d=serviceData[page];return `${subhero(d.headline,d.lead)}<div class="container service-layout"><aside class="service-aside"><div class="aside-card"><span class="aside-icon">${icon('layers')}</span><h3>Explore your options</h3><nav>${services.map(s=>`<a class="${s.id===page?'active':''}" href="${s.id}.html">${s.title}</a>`).join('')}</nav></div><div class="aside-card photo-card">${img(d.side,'A closer look at a household area')}<div><span class="aside-icon">${icon('search')}</span><h3>A useful detail.</h3><p>A clear photo and a short description can make your first enquiry more helpful.</p></div></div><div class="aside-card lime"><span class="check aside-icon">${icon('mail')}</span><h3 style="margin-top:17px">Let’s start here.</h3><p>Tell us what you have noticed and which area is affected.</p>${btn('Make an enquiry','contact.html','dark-button')}</div></aside><main class="service-main"><section class="section" id="overview"><div class="split"><div><h2>${d.intro}</h2><p style="margin-top:20px">${d.body}</p><div class="features">${feature('A clearer brief','Know what to ask.','search')}${feature('Your choice','Compare independent options.','shield')}</div></div>${frame(d.photo,'Specialist inspection related to '+services.find(s=>s.id===page).title)}</div></section><section class="section" id="signs">${head('Details worth noticing.')}<div class="swiper signs-swiper"><div class="swiper-wrapper">${[...d.signs,...d.signs].map(([t,txt,p],i)=>`<div class="swiper-slide pest-card" style="--sign-photo:url('../assets/${[d.photo,d.side,d.compare][i%3]}.avif')">${pest(p)}<span class="sign-category">${services.find(s=>s.id===page).title}</span><h3>${t}</h3><p>${txt}</p><div class="sign-note"><b>${["What to record","What to share","What to ask"][i%3]}</b><p>${["Keep a clear photo and note the location, timing and frequency. Describe changes without disturbing the area.","Tell the provider which spaces are affected, how the pattern has changed and any previous actions taken.","Ask how the area will be assessed, what access is needed and how the findings will be explained."][i%3]}</p></div></div>`).join('')}</div></div><div class="signs-controls"><button class="circle-btn signs-prev" aria-label="Previous signs">${icon('left')}</button><button class="circle-btn signs-next" aria-label="Next signs">${icon('arrow')}</button></div></section>${compare('service-comparison',d.compare,d.pest,'an organised space')}<section class="section" id="service-faq">${head('Before you decide.')}${faq(d.qs)}</section>${serviceExtras()}<section class="section" id="next-step">${banner(page,d.cta)}</section></main></div>`}
function subhero(title,desc=''){return `<section class="subhero"><img class="subhero-photo" src="assets/pest-hero-${({about:'a',contact:'b',household:'e',termites:'d',rodents:'c',privacy:'f',terms:'g',cookies:'h'})[page]}.avif" alt="" fetchpriority="high"><div class="subhero-shade"></div><div class="container"><div class="breadcrumbs"><a href="index.html">Home</a> / ${esc(C.pageTitles[page])}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${cloud()}</section>`}
function about(){return `${subhero('A clearer way forward.','Independent information. Thoughtful questions. A more confident start.')}${section('who-we-are',`<div class="split">${frame('about-team','Pest control professional carrying out a property inspection')}<div><h2>We make options<br>easier to understand.</h2><p style="margin-top:23px">${esc(C.companyName)} is an independent pest control discovery platform. We bring common concerns, service options and useful questions together in one place.</p><p>We do not inspect or treat properties. Our role is to help you start an informed conversation with an independent provider, who is responsible for their own advice, quotation and work.</p><div class="features">${feature('Clear information','Practical context before you enquire.','search')}${feature('Independent choice','Choose the provider that fits your needs.','shield')}</div></div></div>`)}`}
function contact(){return `${subhero('Let’s talk about home.','Tell us what you have noticed. A useful conversation starts with a few details.')}${section('contact',`<div class="contact-grid"><div class="contact-copy"><img class="contact-background" src="assets/contact-photo.avif" alt="Pest professional inspecting a home"><div><h2>Small details.<br>A good beginning.</h2><p>Choose the service closest to your concern and describe the space. Please do not include confidential information.</p><a href="mailto:${esc(C.email)}">${esc(C.email)}</a></div><div><div class="features">${feature('No pressure','Explore your options first.','leaf')}${feature('Clear next steps','Discuss the details that matter.','mail')}</div><p class="mini">${esc(C.disclaimer)}</p></div></div><form class="form" id="contact-form" action="${esc(C.contactEndpoint)}" method="post"><div class="form-row"><label class="field">Full name<input name="name" autocomplete="name" minlength="2" maxlength="100" required placeholder="Your name"></label><label class="field">Email address<input type="email" name="email" autocomplete="email" maxlength="254" required placeholder="you@example.com"></label></div><div class="form-row"><label class="field">Service<select name="service" required><option value="">Choose a service</option><option>Household pests</option><option>Termite control</option><option>Rodent control</option><option>General enquiry</option></select></label><label class="field">Your space<select name="space"><option>Home</option><option>Apartment</option><option>Commercial property</option><option>Other</option></select></label></div><label class="field">What have you noticed?<textarea name="message" minlength="10" maxlength="5000" required placeholder="Tell us where the activity is and when you first noticed it."></textarea></label><label class="honey" aria-hidden="true">Leave empty<input name="website_check" tabindex="-1" autocomplete="off"></label><label class="consent"><input type="checkbox" name="privacy_consent" value="1" required><span>I have read the <a href="privacy.html">Privacy Policy</a> and agree to the use of my details to respond to this enquiry.</span></label><button class="button dark-button" type="submit">Send your enquiry</button><p class="form-status" role="status" aria-live="polite"></p></form></div>`)} `}
const legals={privacy:[['Information you provide','When you submit an enquiry, you provide your name, email, service selection, property context and message. Please include only information needed to explain your request.'],['How information is used','Enquiry information is used to respond to your request and, where explained and agreed, support contact with an independent provider. It is not a booking or a promise of service.'],['Providers and your choice','Independent providers operate under their own terms and privacy notices. Review those notices before supplying further information or agreeing to work.'],['Your questions and requests',`Contact ${esc(C.email)} to ask about your information or request a correction or deletion. Applicable rights and retention requirements depend on the operating jurisdiction.`]],terms:[['About the platform',esc(C.disclaimer)],['Information and availability','The guides provide general context and cannot identify a pest, inspect a property or determine a suitable treatment. Provider availability, methods and pricing vary.'],['Independent services','Any quotation, inspection, treatment, payment or follow-up is agreed directly with the independent provider. Review their credentials, scope and terms before proceeding.'],['Using this website','Use the website lawfully. Do not submit misleading requests, harmful content or another person’s confidential information. Enquiries do not create a service contract.']],cookies:[['Local preferences','This website stores your cookie preference in your browser so the notice does not appear on every page. The preference is stored locally and is not sent to a tracking service.'],['Analytics and advertising','This version does not use advertising cookies or third-party analytics. Fonts, scripts and website images are served with the site.'],['Changing your choice','You can reset the preference using the button below or clear website data in your browser. Declining optional cookies does not prevent navigation or enquiries.'],['Questions',`For questions about website preferences, contact ${esc(C.email)}.`]]};

const legalDetails={privacy:[['Enquiry details','The form asks for your name and email so a response can be addressed to you. Your service selection, property type and message provide context. Do not include payment details, identity documents or information about another person without their permission.'],['Sharing context','If a conversation involves an independent provider, clarify which details are needed and how they will be used before sharing further information. Providers are responsible for their own notices and handling practices.'],['Browser preferences','The cookie-choice notice stores a local preference. This is separate from the information you submit in the enquiry form. You can clear that local preference without sending a deletion request.'],['Keeping information accurate','If your email or enquiry details were entered incorrectly, contact us with enough context to identify the request. Avoid sending unnecessary documents or confidential material in a correction request.']],terms:[['Before agreeing to work','Ask the independent provider for a written description of the scope, exclusions, access requirements and cost. Clarify who is responsible for preparation and how questions or changes will be handled.'],['Illustrations and photographs','Website photographs and interactive pest scenes illustrate topics. They are not evidence of an inspection at your property, verified customer projects or guaranteed treatment outcomes.'],['Enquiries and responses','Submitting the form expresses an interest in discussing a concern. It does not confirm availability, establish a price or reserve an appointment. Those details must be agreed with the relevant provider.'],['Questions about an agreement','For questions about work you have commissioned, refer to the provider and the terms of that agreement. For questions about the website itself, use the email address shown in the footer.']],cookies:[['What the preference stores','The local entry pestora-consent records accepted or declined. The site reads it to decide whether to display the notice again. It does not hold the name, email or message entered in the enquiry form.'],['Where it applies','A preference is specific to the browser and website origin where it was saved. Another device, another browser or a private browsing session may show the notice again.'],['Browser controls','You can remove local website data through your browser settings. Doing so resets the notice on a later visit. Browser settings may also restrict local storage; the site remains navigable when a preference cannot be saved.'],['Essential site delivery','Your browser requests the pages, images, fonts and scripts needed to display the site. Those requests are distinct from advertising or analytics cookies. The hosting service may process technical connection information to deliver the website.']]};
for(const kind of Object.keys(legals))legals[kind].push(...legalDetails[kind]);
function legal(){return `${subhero(esc(C.pageTitles[page]),'Information about using this platform.')}<section class="section"><div class="container legal-layout"><aside><div class="legal-index-heading"><span class="check">${icon('shield')}</span><h3>On this page</h3></div>${legals[page].map(([t],i)=>`<a href="#legal-${i}">${t}</a>`).join('')}</aside><div><div class="legal-intro"><h3>Clear information, in one place.</h3><p>Read how this discovery platform works, what an enquiry means and where to find help with your questions.</p></div><p class="legal-update"><span>${esc(C.legalName)}</span><span>Updated September 2026</span></p>${legals[page].map(([t,d],i)=>`<article id="legal-${i}" data-aos="fade-up"><span class="legal-article-icon">${icon(['shield','layers','home','mail'][i%4])}</span><h2>${t}</h2><p>${d}</p></article>`).join('')}${page==='cookies'?'<button class="button" data-cookie-reset style="margin-top:25px">Change cookie choice</button>':''}</div></div></section>`}
const counterStrip=()=>{const checklists=[
['Kitchen checks','real-roach',12,['Cupboard corners','Shelf joints','Food packaging','Crumb build-up','Waste storage','Sink edges','Pipe openings','Appliance edges','Door seals','Window frames','Floor joints','Pet food storage']],
['Timber details','real-termite',9,['Door frames','Window frames','Skirting boards','Accessible beams','Floor edges','External cladding','Deck edges','Fence posts','Timber near soil']],
['Entry-point','real-mouse',16,['Door sweeps','Garage edges','Pipe openings','Cable openings','Vent covers','Window screens','Threshold joints','Roof edges','External cracks','Outbuilding doors','Utility cupboards','Drain surrounds','Stored materials','Food access','Repeated sounds','Foundation edges']],
['Observation notes','real-ant',7,['Exact room','First sighting','Time of day','Frequency','Visible trail','Nearby food','Nearby moisture']]
];return section('at-a-glance',`<div class="count-shell"><div class="count-strip">${checklists.map(([t,n,count],i)=>`<button class="count-card" type="button" data-count-card="${i}" aria-haspopup="dialog" aria-controls="checklist-dialog">${pest(n,'count-art')}<strong data-count="${count}">${count}</strong><span>${t}</span><small>Open the checklist</small>${icon('plus')}</button>`).join('')}</div><div class="count-dialog" id="checklist-dialog" role="dialog" aria-modal="true" aria-labelledby="checklist-dialog-title-0" hidden><button class="count-dialog-backdrop" type="button" data-count-close aria-label="Close checklist"></button><article class="count-dialog-card" tabindex="-1"><button class="count-close" type="button" data-count-close aria-label="Close checklist">${icon('plus')}</button>${checklists.map(([t,n,count,items],i)=>`<div class="count-panel" data-count-panel="${i}" ${i?'hidden':''}><div class="count-panel-head">${pest(n,'count-panel-art')}<div><span class="tag">Checklist</span><h3 id="checklist-dialog-title-${i}">${t}</h3><p>${count} practical details to keep together before speaking with a provider.</p></div></div><ul>${items.map(t=>`<li>${t}</li>`).join('')}</ul></div>`).join('')}</article></div></div>`)};
const photoUnion=()=>section('one-home',`${head('Every corner. One home.','Move over a photograph to see the whole picture. On touch screens, tap a panel.')}<div class="photo-union">${[['bed','Restful rooms'],['attic','Hidden spaces'],['garage-seal','Protected openings'],['house-clean','Everyday comfort']].map(([n,t],i)=>`<button class="union-panel" data-union="${n}" style="--own:url('../assets/${n}.avif');--slice:${i*100/3}%"><img class="union-own" src="assets/${n}.avif" alt="${t}" loading="eager"><span class="union-shared"></span><span class="union-label">${t}</span></button>`).join('')}</div>`);
const commitment=()=>section('our-purpose',`<div class="commit-grid"><div class="commit-images">${img('flashlight','Close inspection of a dark sheltered corner')}${img('pipe','Precision work around an entry point')}</div><div><h2>Clarity comes<br>before action.</h2><p>A useful pest control conversation starts with the right context. We organise the details so you can describe your concern, understand the options and compare a provider’s proposed work.</p><div class="commit-checks">${['Location and visible signs','Questions about identification','A written scope of work','Preparation and follow-up'].map(t=>`<span>${icon('check')}${t}</span>`).join('')}</div><div class="commit-seal">YOUR HOME. YOUR QUESTIONS.<br>YOUR INDEPENDENT CHOICE.</div></div></div>`);
const promise=()=>section('practical-support',`<div class="support-grid"><div class="support-person"><img src="assets/person-home.avif" alt="Pest control professional with inspection equipment"></div><div><h2>A more useful<br>first conversation.</h2><div class="support-features">${[['Start with the details','Describe the space, the timing and the signs you can see. A precise enquiry helps a provider understand your concern.','search'],['Compare the scope','Ask what is included, what cannot be accessed and how the findings will be explained.','layers'],['Keep your choice','Review the independent provider’s proposal in your own time before agreeing to work.','shield'],['Ask about follow-up','Understand the next review, what to monitor and how to raise questions after a visit.','clock']].map(x=>feature(...x)).join('')}</div></div></div>`,'pale');
const editorialRows=(kind)=>{const sets={household:[['pantry','Food storage','Look at the pattern','Loose packaging, crumbs and quiet shelves can provide useful context. Record the cupboard and the time of sightings. Ask how food storage should be prepared before any proposed work.'],['kitchen','Moisture & shelter','Follow the room','Tell the provider about recurring activity near plumbing or appliances. Avoid moving heavy equipment yourself. A clear description helps define an appropriate inspection.']],termites:[['timber','Accessible timber','Read the visible changes','Photograph accessible changes and describe their exact location. Surface appearance alone does not establish the pest or the extent of damage. Ask what further assessment may be needed.'],['inspection-kitchen','Inspection scope','Understand what is checked','Talk through the accessible rooms, roof spaces and external edges. Request a record of limitations and findings so you can compare the scope of different proposals.']],rodents:[['exterior','Exterior routes','Look at the whole boundary','Describe doors, vents and service openings around the building. A provider can assess access routes and the sequence of any exclusion work.'],['threshold','Entry details','Small openings matter','Share photographs of accessible gaps and note changes over time. Ask how the proposed materials preserve ventilation and access to utilities.']]};return section('field-notes',`<div class="editorial-rows">${sets[kind].map(([n,k,t,d])=>`<article>${img(n,t)}<div><span class="tag">${k}</span><h2>${t}</h2><p>${d}</p><a class="text-link" href="contact.html">Discuss this detail</a></div></article>`).join('')}</div>`)};
const serviceChecklist=(kind)=>{const d=serviceData[kind];return section('inspection-checklist',`${head('Know what to ask.','Six useful details to clarify with an independent provider.')}<div class="scope-list">${['Identification','Accessible areas','Preparation','Proposed method','Written quotation','Follow-up'].map((t,i)=>`<article>${img([d.photo,d.side,d.compare,'flashlight','pipe','fence'][i],t+' context')}<div><h3>${t}</h3><p>${['How will the suspected pest be assessed?','Which spaces are included and which cannot be checked?','What needs to happen before the appointment?','Why is this approach proposed for this property?','What is included in the scope and total cost?','When are findings reviewed and who can you contact?'][i]}</p></div>${icon(['search','home','layers','target','mail','clock'][i])}</article>`).join('')}</div>`)};
const photoAccordion=()=>section('enquiry-guide',`${head('Make your enquiry count.')}<div class="photo-accordion">${[['The place','house-clean','Describe the room, the property type and where you have noticed the signs. Mention whether the concern affects one area or several spaces.'],['The pattern','pest-hero-b','Tell us when you first noticed activity, whether it repeats and whether anything has changed. A brief factual description is more useful than a guessed diagnosis.'],['Your priorities','contact-photo','Mention access arrangements and the questions you want answered. Do not include sensitive personal details; the first enquiry only needs enough context to start a conversation.']].map(([t,n,d],i)=>`<details ${i===0?'open':''}><summary>${icon(['home','clock','shield'][i])}<span>${t}</span></summary><div><p>${d}</p>${img(n,t)}</div></details>`).join('')}</div>`);
const mosaic=()=>section('your-next-conversation',`<div class="mosaic-layout"><div><h2>Good questions.<br>Better context.</h2><p>There is no single plan for every property. Start with what you have noticed and ask a provider to explain how their assessment shapes the next step.</p><p>Keep the proposal, preparation instructions and follow-up arrangements together, so the details remain easy to review.</p>${btn('Explore the guides','household.html')}</div><div class="mosaic-tiles">${img('damage','Close detail of timber changes')}<article><h3>Understand the findings</h3><p>Ask what has been identified and what remains uncertain.</p></article><article><h3>Keep a written record</h3><p>Compare scope, preparation, exclusions and follow-up.</p></article>${img('mouse-garage','Inspection of a sheltered garage')}</div></div>`,'pale');
const guideCards=()=>section('reading-room',`${head('A closer look at home.','Three practical starting points for a more informed enquiry.')}<div class="reading-grid">${[['new-pantry','Household notes','From pantry to plumbing','Track the location and pattern of repeated activity before you describe the concern.','household'],['new-timber','Timber notes','Beyond the surface','Learn what to ask about accessible timber and the limitations of an inspection.','termites'],['new-entry','Entry-point notes','Follow the openings','Explore the questions behind a useful exclusion and monitoring plan.','rodents']].map(([n,k,t,d,l])=>`<a class="reading-card" href="${l}.html">${img(n,t)}<span class="tag">${k}</span><div><h3>${t}</h3><p>${d}</p><span class="text-link">Open the guide</span></div></a>`).join('')}</div>`);
const methodCards=()=>section('inspection-stages',`${head('From signs to a plan.','Discuss each stage with the provider you choose.',true)}<div class="method-four">${[['search','Notice','Record the visible signs and their location. Keep your observations simple and specific.','pest-hero-e'],['layers','Assess','Ask what will be inspected and how findings and access limitations are documented.','flashlight'],['target','Compare','Review the proposed approach, scope and preparation before agreeing to work.','pipe'],['clock','Review','Clarify what to monitor and when the provider recommends a follow-up.','fence']].map(([i,t,d,n])=>`<article>${icon(i)}<h3>${t}</h3><p>${d}</p>${img(n,t+' stage')}</article>`).join('')}</div>`,'pale');
const expandingPanels=()=>section('property-focus',`${head('Different spaces.<br>One thoughtful start.')}<div class="expand-photos">${[['living-room','Living spaces'],['pantry','Food storage'],['garage-seal','Entry points'],['attic','Concealed areas']].map(([n,t],i)=>`<button class="expand-photo ${i===0?'active':''}" ><img src="assets/${n}.avif" alt="${t}" loading="eager"><span>${t}</span></button>`).join('')}</div>`);
function serviceExtras(){return editorialRows(page).replaceAll('class="container"','class="inner-container"')+serviceChecklist(page).replaceAll('class="container"','class="inner-container"')+(page==='household'?methodCards():page==='termites'?mosaic():expandingPanels()+providerList()).replaceAll('class="container"','class="inner-container"')}
const experienceSplit=()=>section('informed-enquiries',`<div class="experience-split"><div><h2>Start informed.<br>Stay in control.</h2><p>A concern can feel less overwhelming when the next questions are clear. Explore the guide that fits your space, then take the details into a conversation with a provider.</p>${feature('Context before a quotation','Describe the activity and ask what assessment is needed before comparing a proposed price.','search')}${feature('A plan you understand','Ask the provider to explain preparation, limitations and the review process in plain language.','shield')}</div><div class="experience-images">${img('new-pantry','A careful pantry inspection')}${img('new-entry','A detailed view of a protected door opening')}</div></div>`);
const questionQuotes=()=>section('conversation-prompts',`<div class="quote-layout">${img('contact-photo','Specialist checking an interior detail')}<div><h2>Ask the questions<br>that matter.</h2><p>Use these prompts when you discuss a proposed inspection. They help turn a general enquiry into a conversation about your actual property.</p><div class="quote-cards"><blockquote><span>“</span><p>What did you find, what remains uncertain, and which parts of the property could not be assessed?</p><cite>Understanding the assessment</cite></blockquote><blockquote><span>“</span><p>What is included in the plan, how should I prepare, and how will we know when to review it?</p><cite>Understanding the next step</cite></blockquote></div></div></div>`);
const providerList=()=>section('talk-through-the-plan',`${head('A plan worth understanding.','',true)}<div class="provider-layout"><div>${[['search','The inspection','Confirm the areas to be assessed and how the findings are recorded. Ask about access limitations before a visit.'],['target','The method','Discuss why the proposed approach suits the identified pest and conditions. Ask about preparation and access instructions.'],['clock','The review','Clarify how activity will be monitored and when the provider will reassess the plan. Keep the contact details with your records.']].map(([i,t,d])=>`<article>${icon(i)}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div><img src="assets/person-household.avif" alt="Pest control specialist with professional inspection equipment"></div>`);
const caseBand=()=>section('around-the-property',`<div class="case-band parallax-panel" style="--panel-photo:url('../assets/exterior.avif')">${head('Look around the property.','Different spaces give an inspector different details to consider.',true)}<div>${[['pantry','Sheltered food storage'],['new-entry','Door and service openings'],['new-timber','Accessible timber'],['bed','Quiet interior spaces']].map(([n,t])=>`<article>${img(n,t)}<h3>${t}</h3><p>Record what you notice and ask how this area fits into the inspection scope.</p></article>`).join('')}</div></div>`);
const processBand=()=>section('a-useful-brief',`<div class="process-band parallax-panel" style="--panel-photo:url('../assets/about-team.avif')">${[['Notice','The location'],['Record','The pattern'],['Discuss','The scope'],['Review','The next step']].map(([t,d])=>`<div><strong>${t}</strong><span>${d}</span></div>`).join('')}</div><div class="process-bottom"><div><h3>Small details make<br>a useful starting point.</h3><p>Your observations help describe the concern before any provider assesses it.</p></div><div><h2>Make room for clarity.</h2><p>Keep your photographs and notes together. Describe accessible signs without disturbing the area, and ask the provider to explain how those observations inform the inspection.</p><ul><li>Where the activity appeared</li><li>When it was first noticed</li><li>What has changed since then</li></ul></div></div>`);

function additions(){if(page==='home')return counterStrip()+photoUnion()+guideCards()+caseBand()+section('home-next-step',banner('home','Your home deserves<br>a calmer chapter.'),'banner-section');if(page==='about')return commitment()+promise()+mosaic()+questionQuotes();if(page==='contact')return experienceSplit()+methodCards();if(serviceData[page])return '';return ''}

document.title=`${C.pageTitles[page]} | ${C.browserTitle||C.companyName}`;document.querySelector('link[rel="icon"]').href=C.favicon;
document.getElementById('app').innerHTML=`<a class="skip-link" href="#main">Skip to content</a><header class="header"><div class="container header-inner">${brand()}<nav class="nav"><a href="index.html">${esc(C.nav.home)}</a><a href="about.html">${esc(C.nav.about)}</a><div class="dropdown"><button aria-haspopup="true">${esc(C.nav.services)}</button><div class="dropdown-menu">${services.map(s=>`<a href="${s.id}.html">${s.title}</a>`).join('')}</div></div><a href="contact.html">${esc(C.nav.contact)}</a></nav>${btn('Find your next step')}<button class="burger" aria-label="Open navigation" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span></button></div></header><nav class="mobile-menu" id="mobile-menu" aria-hidden="true"><div class="menu-art" aria-hidden="true"><img src="assets/real-roach.avif" class="menu-pest menu-pest-one" alt=""><img src="assets/real-ant.avif" class="menu-pest menu-pest-two" alt=""><img src="assets/web-overlay.avif" class="menu-web" alt=""></div><a href="index.html">Home</a><a href="about.html">About us</a><div class="mobile-services">${services.map(s=>`<a href="${s.id}.html"><span class="menu-service-icon">${pest(s.pest)}</span><span>${s.title}</span>${icon('arrow')}</a>`).join('')}</div><a href="contact.html">Contact</a>${cloud()}</nav><div id="main">${page==='home'?home():serviceData[page]?service():page==='about'?about():page==='contact'?contact():legal()}${additions()}</div><footer class="footer"><div class="container"><div class="footer-top">${brand()}<div><span class="mini">A useful conversation starts here</span><a href="mailto:${esc(C.email)}">${esc(C.email)}</a></div>${btn('Make an enquiry')}</div><div class="footer-grid"><div><h3>Your home. A clearer next step.</h3><p>${esc(C.disclaimer)}</p></div><div><h3>Explore</h3><a href="index.html">Home</a><a href="about.html">About us</a><a href="contact.html">Contact</a></div><div><h3>Pest control guides</h3>${services.map(s=>`<a href="${s.id}.html">${s.title}</a>`).join('')}</div></div><div class="footer-bottom"><span>© ${esc(C.copyright)} ${esc(C.legalName)}. All rights reserved.</span><nav><a href="privacy.html">Privacy Policy</a><a href="terms.html">Terms of Use</a><a href="cookies.html">Cookie Policy</a></nav></div></div></footer><div class="cookie" hidden><p>Only local preferences. Choose how this site remembers your visit. <a href="cookies.html"><u>Cookie policy</u></a></p><button class="button" data-cookie="accepted">Accept</button><button class="decline" data-cookie="declined">Decline</button></div><div class="page-loader" aria-hidden="true"><img class="loader-web" src="assets/web-overlay.avif" alt=""><img class="loader-web loader-web-two" src="assets/web-overlay.avif" alt=""><div class="loader-center"><div class="loader-emblem"><img src="${esc(C.logo)}" alt=""></div><strong>${esc(C.companyName)}</strong><span>A calmer space awaits.</span><div class="loader-progress"><i></i></div></div></div>`;
document.querySelectorAll('#main > .section, #main > .compare-section, .service-main > section + section').forEach((section,i)=>{if(i%2===0){const divider=document.createElement('div');divider.className='timber-divider';divider.setAttribute('aria-hidden','true');divider.innerHTML='<img src="assets/plank.avif" alt="" width="1600" height="120">';section.before(divider)}});
document.querySelectorAll('[style]').forEach(el=>{const value=el.getAttribute('style');if(/url\('(?:\.\.\/)?assets\//.test(value))el.setAttribute('style',value.replace(/url\('(?:\.\.\/)?assets\/([^']+)'\)/g,(_,path)=>`url('${new URL('assets/'+path,document.baseURI).href}')`))});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(window.AOS)AOS.init({once:true,duration:550,offset:40,disable:reduced});
if(!reduced){const titleObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('typing-visible');titleObserver.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('h1,h2,h3').forEach(h=>{let index=0;const walker=document.createTreeWalker(h,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);h.setAttribute('aria-label',h.textContent);nodes.forEach(node=>{const fragment=document.createDocumentFragment();node.textContent.split(/(\s+)/).forEach(word=>{if(/^\s+$/.test(word)){fragment.append(document.createTextNode(word));return}const wrap=document.createElement('span');wrap.className='typing-word';wrap.setAttribute('aria-hidden','true');for(const char of word){const span=document.createElement('span');span.className='typing-char';span.textContent=char;span.style.setProperty('--delay',Math.min(index++*24,1400)+'ms');wrap.append(span)}fragment.append(wrap)});node.replaceWith(fragment)});h.classList.add('typing-heading');titleObserver.observe(h)})}
const burger=document.querySelector('.burger'),menu=document.querySelector('.mobile-menu');function toggleMenu(open){burger.setAttribute('aria-expanded',open);burger.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.classList.toggle('open',open);menu.setAttribute('aria-hidden',!open);menu.inert=!open;document.body.classList.toggle('lock',open)}menu.inert=true;burger.onclick=()=>toggleMenu(burger.getAttribute('aria-expanded')!=='true');document.addEventListener('keydown',e=>{if(e.key==='Escape')toggleMenu(false);if(e.key==='Tab'&&menu.classList.contains('open')){const links=[burger,...menu.querySelectorAll('a')];const last=links.at(-1);if(e.shiftKey&&document.activeElement===burger){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();burger.focus()}}});
if(window.Swiper&&document.querySelector('.service-swiper'))new Swiper('.service-swiper',{loop:true,slidesPerView:1,spaceBetween:20,speed:650,grabCursor:true,autoplay:reduced?false:{delay:4200,disableOnInteraction:false,pauseOnMouseEnter:true},pagination:{el:'.swiper-pagination',clickable:true},navigation:{prevEl:'.swiper-prev',nextEl:'.swiper-next'},breakpoints:{650:{slidesPerView:2},1050:{slidesPerView:3}},a11y:{enabled:true}});
document.querySelectorAll('.compare input').forEach(input=>input.oninput=()=>input.closest('.compare').style.setProperty('--position',input.value+'%'));
