const spots=[['Under the threshold','A small gap can be easy to miss. Ask a provider to assess whether the threshold, door sweep or surrounding joint needs attention.'],['Around the frame','Worn joints and changing seals can create sheltered edges. Clear photographs can help you describe the concern.'],['In quiet corners','Undisturbed corners may conceal signs of activity. Note where you see changes and share the pattern with a provider.']];let spot=0;function setSpot(i){spot=(i+3)%3;document.getElementById('spot-title').textContent=spots[spot][0];document.getElementById('spot-description').textContent=spots[spot][1];document.querySelectorAll('[data-spot]').forEach((b,n)=>b.classList.toggle('active',n===spot))}document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>setSpot(+b.dataset.spot));document.querySelector('[data-spot-prev]')?.addEventListener('click',()=>setSpot(spot-1));document.querySelector('[data-spot-next]')?.addEventListener('click',()=>setSpot(spot+1));
