const countDialog=document.querySelector('.count-dialog'),countDialogCard=document.querySelector('.count-dialog-card');let lastCountTrigger=null;function closeCountDialog(){if(!countDialog)return;countDialog.hidden=true;document.body.classList.remove('lock');document.querySelectorAll('[data-count-card]').forEach(card=>card.classList.remove('active'));lastCountTrigger?.focus()}document.querySelectorAll('[data-count-card]').forEach(button=>button.addEventListener('click',()=>{const index=+button.dataset.countCard;lastCountTrigger=button;document.querySelectorAll('[data-count-card]').forEach(card=>card.classList.toggle('active',card===button));document.querySelectorAll('[data-count-panel]').forEach(panel=>{panel.hidden=+panel.dataset.countPanel!==index});countDialog?.setAttribute('aria-labelledby',`checklist-dialog-title-${index}`);countDialog.hidden=false;document.body.classList.add('lock');countDialogCard?.focus()}));document.querySelectorAll('[data-count-close]').forEach(button=>button.addEventListener('click',closeCountDialog));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&countDialog&&!countDialog.hidden)closeCountDialog()});
const cookie=document.querySelector('.cookie');try{cookie.hidden=!!localStorage.getItem('pestora-consent')}catch{cookie.hidden=false}document.querySelectorAll('[data-cookie]').forEach(b=>b.onclick=()=>{try{localStorage.setItem('pestora-consent',b.dataset.cookie)}catch{}cookie.hidden=true});document.querySelector('[data-cookie-reset]')?.addEventListener('click',()=>{try{localStorage.removeItem('pestora-consent')}catch{}cookie.hidden=false});
const loader=document.querySelector('.page-loader');document.querySelectorAll('a[href$=".html"]').forEach(a=>a.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0||reduced)return;e.preventDefault();loader.classList.add('active');setTimeout(()=>location.href=a.href,340)}));window.addEventListener('pageshow',()=>loader.classList.remove('active'));
const form=document.getElementById('contact-form');let sending=false;if(form)form.addEventListener('submit',async e=>{e.preventDefault();if(sending||!form.reportValidity())return;sending=true;const button=form.querySelector('[type=submit]'),status=form.querySelector('.form-status');button.disabled=true;status.textContent='Sending your enquiry…';const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(C.contactEndpoint,{method:'POST',body:new FormData(form),headers:{Accept:'application/json'},signal:controller.signal});if(!response.headers.get('content-type')?.includes('application/json'))throw Error('The enquiry service is not available here. Please contact us by email.');const data=await response.json();if(!response.ok||data.success!==true)throw Error(data.message||'Your message could not be sent. Please try again.');status.textContent=C.formSuccessMessage;form.reset()}catch(err){status.textContent=err.name==='AbortError'?'The request timed out. Please try again.':err.message}finally{clearTimeout(timeout);sending=false;button.disabled=false}});


