const heroFrames=[...document.querySelectorAll('.hero-frame')];let heroIndex=0,heroPaused=reduced,heroTimer;
function showHero(i){if(!heroFrames[i].complete||!heroFrames[i].naturalWidth)return;heroIndex=i;heroFrames.forEach((f,n)=>f.classList.toggle('is-active',n===i));document.querySelectorAll('[data-hero-slide]').forEach((b,n)=>b.setAttribute('aria-pressed',n===i))}
function runHero(){clearInterval(heroTimer);if(heroFrames.length&&!heroPaused&&!document.hidden)heroTimer=setInterval(()=>{const next=(heroIndex+1)%heroFrames.length;if(heroFrames[next].complete&&heroFrames[next].naturalWidth)showHero(next)},4000)}
document.querySelectorAll('[data-hero-slide]').forEach(b=>b.addEventListener('click',()=>{showHero(+b.dataset.heroSlide);runHero()}));
const heroPause=document.querySelector('.hero-pause');if(heroPause){heroPause.setAttribute('aria-pressed',heroPaused);heroPause.setAttribute('aria-label',heroPaused?'Play slideshow':'Pause slideshow');heroPause.innerHTML=icon(heroPaused?'play':'pause');heroPause.onclick=()=>{heroPaused=!heroPaused;heroPause.setAttribute('aria-pressed',heroPaused);heroPause.setAttribute('aria-label',heroPaused?'Play slideshow':'Pause slideshow');heroPause.innerHTML=icon(heroPaused?'play':'pause');runHero()}}runHero();document.addEventListener('visibilitychange',runHero);
if(!reduced){let parallaxPending=false;const heroShell=document.querySelector('.hero-shell'),subPhoto=document.querySelector('.subhero-photo');function parallax(){if(parallaxPending)return;parallaxPending=true;requestAnimationFrame(()=>{if(scrollY<900){if(heroShell)heroShell.style.setProperty('--hero-shift',`${scrollY*.065}px`);if(subPhoto)subPhoto.style.transform=`translateY(${Math.min(scrollY*.14,55)}px) scale(1.16)`}parallaxPending=false})}window.addEventListener('scroll',parallax,{passive:true});parallax();loader.classList.add('active');setTimeout(()=>loader.classList.remove('active'),400)}
const legalArticles=[...document.querySelectorAll('.legal-layout article')];if(legalArticles.length){const legalObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)document.querySelectorAll('.legal-layout aside>a').forEach(a=>{const current=a.getAttribute('href')==='#'+entry.target.id;a.classList.toggle('is-current',current);if(current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})})},{rootMargin:'-10% 0px -60% 0px',threshold:0});legalArticles.forEach(article=>legalObserver.observe(article))}

const countObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;const el=e.target,end=+el.dataset.count;countObserver.unobserve(el);if(reduced)return;let start;function tick(t){start??=t;const progress=Math.min((t-start)/1100,1);el.textContent=Math.round(end*(1-Math.pow(1-progress,3)));if(progress<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}),{threshold:.5});document.querySelectorAll('[data-count]').forEach(el=>countObserver.observe(el));
